import{_ as e,o as a,c as r,ag as i}from"./chunks/framework.Drp2S_UI.js";const c=JSON.parse('{"title":"Benchmark: typing and sustained deletion","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/benchmark.md","filePath":"en/guide/benchmark.md","lastUpdated":1792752159000}'),d={name:"en/guide/benchmark.md"};function n(s,t,l,o,h,g){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="benchmark-typing-and-sustained-deletion" tabindex="-1">Benchmark: typing and sustained deletion <a class="header-anchor" href="#benchmark-typing-and-sustained-deletion" aria-label="Permalink to &quot;Benchmark: typing and sustained deletion&quot;">​</a></h1><p>Updated 2026-10-23. These results cover the original baseline, the preceding optimization and the final position/query reuse and Worker recovery fixes. All optimized results use explicit experimental configuration; the default remains <code>baseline</code>. See <a href="./lab.html">configuration and fallback</a>.</p><h2 id="method" tabindex="-1">Method <a class="header-anchor" href="#method" aria-label="Permalink to &quot;Method&quot;">​</a></h2><p>Apple M1 Pro, 8 logical CPUs, 16 GiB, Darwin 25.4.0, Node 24.19.0. Fixed NotoNaskhArabic-Regular.ttf SHA256: <code>67b5a525a661b607971fbd3f96a81b89d3a768e74534fca84f18ac97e6fab72f</code>.</p><p>Chrome changed from 155.0.8059.85 in historical runs to 155.0.8059.86 in the final runs. These are same-machine historical trends, <strong>not a strict same-browser A/B</strong>; timing differences cannot be attributed entirely to code changes.</p><p>Standard cases use middle edits, paging, history on, paragraph cache off, DPR 1, one warmup and 2Hz for 10 seconds (20 operations per configuration). The initial baseline has one trial; preceding and final results have three. Tables compare fixed trial 0, rather than selecting the fastest trial. Units are milliseconds. Input uses the input handler; deletion uses the keydown handler.</p><p>Geometry commit is an event-to-geometry proxy. Offer-to-geometry also includes driver queueing. Neither measures screen presentation. Inclusive stages overlap and must not be added together.</p><h2 id="standard-handler-p50" tabindex="-1">Standard handler P50 <a class="header-anchor" href="#standard-handler-p50" aria-label="Permalink to &quot;Standard handler P50&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Document</th><th>Action</th><th style="text-align:right;">Initial</th><th style="text-align:right;">Preceding</th><th style="text-align:right;">Final</th><th style="text-align:right;">Reduction vs preceding</th></tr></thead><tbody><tr><td>100 paragraphs</td><td>input</td><td style="text-align:right;">339.6</td><td style="text-align:right;">30.1</td><td style="text-align:right;">6.3</td><td style="text-align:right;">79.1%</td></tr><tr><td>100 paragraphs</td><td>backspace</td><td style="text-align:right;">357.1</td><td style="text-align:right;">30.7</td><td style="text-align:right;">7.5</td><td style="text-align:right;">75.6%</td></tr><tr><td>100 paragraphs</td><td>delete</td><td style="text-align:right;">352.6</td><td style="text-align:right;">31.2</td><td style="text-align:right;">7.2</td><td style="text-align:right;">76.9%</td></tr><tr><td>1000 paragraphs</td><td>input</td><td style="text-align:right;">5296.0</td><td style="text-align:right;">287.3</td><td style="text-align:right;">34.8</td><td style="text-align:right;">87.9%</td></tr><tr><td>1000 paragraphs</td><td>backspace</td><td style="text-align:right;">5349.9</td><td style="text-align:right;">277.8</td><td style="text-align:right;">32.1</td><td style="text-align:right;">88.4%</td></tr><tr><td>1000 paragraphs</td><td>delete</td><td style="text-align:right;">5358.3</td><td style="text-align:right;">267.0</td><td style="text-align:right;">35.3</td><td style="text-align:right;">86.8%</td></tr><tr><td>One long paragraph</td><td>input</td><td style="text-align:right;">471.1</td><td style="text-align:right;">197.1</td><td style="text-align:right;">189.8</td><td style="text-align:right;">3.7%</td></tr><tr><td>One long paragraph</td><td>backspace</td><td style="text-align:right;">480.2</td><td style="text-align:right;">194.0</td><td style="text-align:right;">194.7</td><td style="text-align:right;">-0.4%</td></tr><tr><td>One long paragraph</td><td>delete</td><td style="text-align:right;">469.7</td><td style="text-align:right;">190.5</td><td style="text-align:right;">191.9</td><td style="text-align:right;">-0.7%</td></tr><tr><td>Large table</td><td>input</td><td style="text-align:right;">42.4</td><td style="text-align:right;">19.9</td><td style="text-align:right;">20.0</td><td style="text-align:right;">-0.5%</td></tr><tr><td>Large table</td><td>backspace</td><td style="text-align:right;">39.5</td><td style="text-align:right;">19.1</td><td style="text-align:right;">21.7</td><td style="text-align:right;">-13.6%</td></tr><tr><td>Large table</td><td>delete</td><td style="text-align:right;">43.1</td><td style="text-align:right;">20.8</td><td style="text-align:right;">20.7</td><td style="text-align:right;">0.5%</td></tr></tbody></table><p>Negative reduction means slower. Final three-trial P50 ranges for input are 6.3–8.0ms (100 paragraphs), 34.0–35.3ms (1000), 189.8–190.5ms (long paragraph), and 19.9–23.5ms (large table). The full <a href="./../../guide/benchmark.html#本次三轮波动及尾延迟">three-trial tail table</a> retains all outliers: thousand-paragraph Backspace/Delete max reached 1491.8/1435.5ms, and table input P95 reached 127.3ms. These tails must not be hidden by median improvements.</p><h2 id="position-and-query-work" tabindex="-1">Position and query work <a class="header-anchor" href="#position-and-query-work" aria-label="Permalink to &quot;Position and query work&quot;">​</a></h2><p>Thousand-paragraph input, trial 0, mean inclusive cost per key:</p><table tabindex="0"><thead><tr><th>Stage</th><th style="text-align:right;">Preceding</th><th style="text-align:right;">Final</th><th style="text-align:right;">Reduction</th></tr></thead><tbody><tr><td>positions</td><td style="text-align:right;">281.64</td><td style="text-align:right;">8.43</td><td style="text-align:right;">97.0%</td></tr><tr><td>queryIndexBuild (inside positions)</td><td style="text-align:right;">54.41</td><td style="text-align:right;">2.29</td><td style="text-align:right;">95.8%</td></tr><tr><td>flow</td><td style="text-align:right;">15.87</td><td style="text-align:right;">17.31</td><td style="text-align:right;">-9.1%</td></tr></tbody></table><p>Across 20 edits, 2730 position elements were computed and 776180 reused, excluding restored prefix references. Global metadata and row/paragraph directories still require traversal; this is not constant-time editing.</p><h2 id="sustained-worker-editing" tabindex="-1">Sustained Worker editing <a class="header-anchor" href="#sustained-worker-editing" aria-label="Permalink to &quot;Sustained Worker editing&quot;">​</a></h2><p>All pressure cases run at 30Hz. Hundred-paragraph long pressure uses 30 seconds/900 edits; thousand-paragraph and transfer cases use 10 seconds/300 edits. Do not combine different capacities or durations into one percentage.</p><table tabindex="0"><thead><tr><th>Case / action</th><th style="text-align:right;">handler P95</th><th style="text-align:right;">geometry P95</th><th style="text-align:right;">offer-to-geometry P95</th><th style="text-align:right;">Drain time</th></tr></thead><tbody><tr><td>100 paragraphs / 30s / input</td><td style="text-align:right;">5.8</td><td style="text-align:right;">179.3</td><td style="text-align:right;">217.1</td><td style="text-align:right;">30021.0</td></tr><tr><td>100 paragraphs / 30s / backspace</td><td style="text-align:right;">25.5</td><td style="text-align:right;">25.4</td><td style="text-align:right;">72.4</td><td style="text-align:right;">30351.1</td></tr><tr><td>1000 paragraphs / input / trial 0</td><td style="text-align:right;">2.6</td><td style="text-align:right;">148.7</td><td style="text-align:right;">1356.6</td><td style="text-align:right;">11392.0</td></tr><tr><td>1000 paragraphs / input / trial 1</td><td style="text-align:right;">2.5</td><td style="text-align:right;">1308.2</td><td style="text-align:right;">2214.5</td><td style="text-align:right;">10958.3</td></tr><tr><td>1000 paragraphs / input / trial 2</td><td style="text-align:right;">2.4</td><td style="text-align:right;">1313.5</td><td style="text-align:right;">2177.6</td><td style="text-align:right;">10906.7</td></tr></tbody></table><p>Hundred-paragraph 30s Backspace improved from handler P95 67.5 to 25.5ms, offer-to-geometry P95 6718.4 to 72.4ms, and drain time 36.13 to 30.35s. The mirror changed from ready=false / needsResync=true to ready=true / needsResync=false. Final requests and buffered edits were zero; no backend fault was recorded, one session start includes initialization, and peak buffered edits were 25. Full undo/redo matched with one history group.</p><p>Deletion commits synchronous incremental geometry and coalesces paint. Input can still use asynchronous layout; mirror edits are acknowledged in ordered batches. Faults/budget overflow rebuild from the authoritative model after idle or explicit draining.</p><p>Transfer input geometry P95 was 138.2/144.3/143.3ms; transfer Backspace was 11.5/12.3/12.1ms. All final pressure mirrors were ready without pending requests or edits. See the <a href="./../../guide/benchmark.html#持续输入删除和-worker">complete pressure matrix</a> and raw data below. Thousand-paragraph flow windows still consumed about 8.2–8.5 seconds, with two geometry P95 results around 1.3 seconds.</p><h2 id="validation-and-release-status" tabindex="-1">Validation and release status <a class="header-anchor" href="#validation-and-release-status" aria-label="Permalink to &quot;Validation and release status&quot;">​</a></h2><p>The full Vitest run passed 169 files/1072 tests; after final geometry, destruction and idle-boundary fixes, four targeted files/50 tests passed again. TypeScript, ESLint and the final library build passed. Final Chrome differential checks covered six groups/four modes, 348 structural comparisons and exact exported RGBA equality, including Unicode, RTL, tables, history and crash/budget recovery, with no page errors. Final benchmark data covers 50 cases/5280 operations.</p><p>Six create/edit/destroy cycles cleared workers, canvases, observers, pending requests and path caches. Forced-GC JS heap ranged from 14223020 to 14232228 bytes (about 13.56–13.57MiB). This supports short-term JS cleanup only, not long-term native/WASM/GPU memory stability.</p><p>Release status remains <strong>hold</strong> against fixed handler P95 ≤8ms and geometry P95 ≤32ms budgets. Keep <code>baseline</code> as default, <code>sync</code> opt-in, Worker experimental and transfer deferred. OS IME/key repeat, actual presentation, long-term memory and fresh Firefox/WebKit checks remain required. Historical browser results do not validate the latest fixes. Follow <a href="./engineering-records.html">testing and acceptance</a> to regenerate evidence.</p><h2 id="retained-evidence" tabindex="-1">Retained evidence <a class="header-anchor" href="#retained-evidence" aria-label="Permalink to &quot;Retained evidence&quot;">​</a></h2><ul><li><a href="../../guide/performance-baselines/perf01-2026-10-22.json">Initial standard baseline</a>, <a href="../../guide/performance-baselines/perf01-pressure-2026-10-22.json">initial pressure</a></li><li><a href="../../guide/performance-baselines/perf21-sync-2026-10-23.json">Pre-fix sync</a>, <a href="../../guide/performance-baselines/perf21-worker-long-pressure-2026-10-23.json">pre-fix sustained editing</a></li><li><a href="../../guide/performance-baselines/perf-position-worker-sync-2026-10-23.json">Final sync, three trials</a></li><li><a href="../../guide/performance-baselines/perf-position-worker-long-2026-10-23.json">Final sustained editing</a></li><li><a href="../../guide/performance-baselines/perf-position-worker-1000-2026-10-23.json">Final thousand-paragraph Worker</a></li><li><a href="../../guide/performance-baselines/perf-position-worker-transfer-2026-10-23.json">Final transfer</a></li><li><a href="../../guide/performance-baselines/perf-position-worker-uninstrumented-2026-10-23.json">Final uninstrumented control</a></li></ul><p>The <a href="./../../guide/benchmark.html">complete Chinese report</a> includes all three-trial percentiles and pressure rows. Raw evidence retains environment, source hashes, events, stages, queues and correctness results. Intermediate/failed runs, traces, screenshots and disposable build logs are excluded from version control.</p>',27)])])}const u=e(d,[["render",n]]);export{c as __pageData,u as default};
